class Solution {
  public long minTime(int[] skill, int[] mana) {
    int n = skill.length, m = mana.length;
    long[] prefix = new long[n + 1];
    for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + skill[i];
    // start time of potion j: every wizard must be free when the potion reaches them
    long start = 0;
    for (int j = 1; j < m; j++) {
      long best = Long.MIN_VALUE;
      for (int i = 0; i < n; i++) {
        best = Math.max(best, mana[j - 1] * prefix[i + 1] - mana[j] * prefix[i]);
      }
      start += best;
    }
    return start + mana[m - 1] * prefix[n];
  }
}
